-- p17_ext_versions, node 1. Generated by gen.py from special/src/p17_ext_versions.sql.
-- Usage:  psql -X -q -v ON_ERROR_STOP=1 -d <database> -f p17_ext_versions_node1.sql
--
-- Case P17: the nodes have other versions of an extension.
-- Stand: two servers where hstore, citext, ltree, pgvector or PostGIS are
--        installed in different versions (a new server installs its default).
-- Run:   the same data on both.
-- Expect: sp.p17_ext_versions shows the versions as data: the rows of the
--         extensions that differ are reported. sp.p17_ext_values holds values
--         that the extension computed and printed on its node: any difference
--         there is a change of output or of semantics between the versions.

SET client_min_messages = warning;
SET TimeZone = 'UTC';
SET DateStyle = 'ISO, MDY';
SET IntervalStyle = 'postgres';
SET default_transaction_read_only = off;
CREATE SCHEMA IF NOT EXISTS sp;
CREATE EXTENSION IF NOT EXISTS hstore;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS ltree;
DROP TABLE IF EXISTS sp.p17_ext_versions, sp.p17_ext_values;
CREATE TABLE sp.p17_ext_versions (extname text PRIMARY KEY, extversion text);
INSERT INTO sp.p17_ext_versions SELECT extname, extversion FROM pg_extension;
COMMENT ON TABLE sp.p17_ext_versions IS 'P17: one changed row for each extension whose version differs';

CREATE TABLE sp.p17_ext_values (id int PRIMARY KEY, what text, v text);
INSERT INTO sp.p17_ext_values VALUES
	(1, 'hstore output', ('b=>2, a=>1, c=>NULL, "d e"=>"f,g"'::hstore)::text),
	(2, 'hstore to json', hstore_to_json_loose('a=>1, b=>1.50, c=>t')::text),
	(3, 'citext compare', ('Stra' || U&'\00DF' || 'e' = 'STRASSE'::citext)::text),
	(4, 'ltree output', ('Top.Science.Astronomy'::ltree)::text),
	(5, 'ltree subpath', subpath('Top.Science.Astronomy.Stars', 1, 2)::text);
DO $$
BEGIN
	IF EXISTS (SELECT FROM pg_extension WHERE extname = 'vector') THEN
		EXECUTE $q$INSERT INTO sp.p17_ext_values VALUES
			(10, 'vector output', ('[1,2.5,3.14159274]'::vector)::text),
			(11, 'vector distance', ('[1,2,3]'::vector <-> '[3,2,1]'::vector)::text),
			(12, 'vector cosine', ('[1,2,3]'::vector <=> '[3,2,1]'::vector)::text)$q$;
	END IF;
	IF EXISTS (SELECT FROM pg_extension WHERE extname = 'postgis') THEN
		EXECUTE $q$INSERT INTO sp.p17_ext_values VALUES
			(20, 'geometry output', ('SRID=4326;POINT(1 2)'::geometry)::text),
			(21, 'geometry text', ST_AsText('LINESTRING(0 0,1 1.5)'::geometry)),
			(22, 'geography distance', ST_Distance('SRID=4326;POINT(0 0)'::geography, 'SRID=4326;POINT(1 1)'::geography)::text),
			(23, 'geometry equality', ('LINESTRING(0 0,1 1)'::geometry = 'LINESTRING(1 1,0 0)'::geometry)::text)$q$;
	END IF;
END $$;
COMMENT ON TABLE sp.p17_ext_values IS 'P17: match, unless a version of an extension prints or computes a value in another way';
